                target: txt
                text: "移出去了"
            }
        },
        //鼠标移入状态下按钮为黄色，并改变文本
        State {
            name: "hovered"
            PropertyChanges {
                target: btn
                color: "yellow"
            }
            PropertyChanges {
                target: txt
                text: "放进来了"
            }
        }
    ]

    //过渡动画
    transitions: [
        //从normal状态过渡到hovered状态
        Transition {
            from: "normal"
            to: "hovered"

			//颜色过渡动画
            ColorAnimation {
                target: btn
                //由于btn中hovered和normal状态之间已经有了两种颜色所以不需要写from和to
