        //从hovered状态过渡到normal状态
        Transition {
            from: "hovered"
            to: "normal"

            //颜色过渡动画
            ColorAnimation {
                target: btn
                //由于btn中hovered和normal状态之间已经有了两种颜色所以不需要写from和to
