## 61、ListView：视图、代理、模型

<span style="background: yellow;">视图：listview</span>

<span style="background: yellow;">代理：定义视图中的每一条数据该长什么样子</span>

<span style="background: yellow;">模型：代指数据：listmode</span>

```c++
//定义模型
ListModel {
    id: listModel

    //定义模型数据，属性名称：属性值
    ListElement {
        name: "张三"
        age: 15
    }
    ListElement {
        name: "张三A"
        age: 15
    }
    ListElement {
        name: "王三B"
        age: 15
    }
    ListElement {
        name: "王三C"
        age: 15
    }
    ListElement {
        name: "张三D"
        age: 15
    }
    ListElement {
        name: "王三E"
        age: 15
    }
    ListElement {
        name: "张三F"
        age: 15
    }
    ListElement {
        name: "李三G"
        age: 15
    }
    ListElement {
        name: "李三H"
        age: 15
    }
    ListElement {
        name: "李三I"
        age: 15
    }
}

ListView {
    id: listview
    anchors.fill: parent
    anchors.rightMargin: 200

    //模型
    // model: ["A", "B", "C"]
    model: listModel

    //代理
    delegate: Item {
        width: listview.width
        height: 50

        Rectangle {
            id: leftRect
            anchors.left: parent.left
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "red"
            border.color: "yellow"
            border.width: 1

            //用text显示模型
            Text {
                anchors.centerIn: parent
                font.pixelSize: 30
                //获取模型的数据，modelData无法通过代码补全和官方文档查询，但实际存在
                //并且只有model为原始的字符串数组modelDate才会生效
                //使用listmode时，modelDate会不定义，若想要显示数据，则直接写listelement的属性名称，多个属性可以加号连接
                text: name
            }
        }

        Rectangle {
            id: rightRect
            anchors.right: parent.right
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "red"
            border.color: "yellow"
            border.width: 1

            //用text显示模型
            Text {
                anchors.centerIn: parent
                font.pixelSize: 30
                //获取模型的数据，modelData无法通过代码补全和官方文档查询，但实际存在
                //并且只有model为原始的字符串数组modelDate才会生效
                //使用listmode时，modelDate会不定义，若想要显示数据，则直接写listelement的属性名称，多个属性可以加号连接
                text: age
            }
        }

        MouseArea {
            anchors.fill: parent
            hoverEnabled: true

            onEntered: {
                //将鼠标 所在代理的行索引 赋值给 视图当前索引
                listview.currentIndex = index
                //将name和age传递给高光代理
                listview.highlightItem.setText(name, age)
            }
        }
    }

    //表头
    header: Item {
        width: listview.width
        height: 50
        z: 3//设置层级避免滚动时，代理覆盖表头

        Rectangle {
            anchors.left: parent.left
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "green"

            Text {
                anchors.centerIn: parent
                font.pixelSize: 30
                text: "姓名"
            }
        }

        Rectangle {
            anchors.right: parent.right
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "green"

            Text {
                anchors.centerIn: parent
                font.pixelSize: 30
                text: "年龄"
            }
        }
    }

    //设置表头位置，默认是第一行，OverlayHeader表示第一行并固定，更多请查看文档
    headerPositioning: ListView.OverlayHeader

    //表尾
    footer: Rectangle {
        width: listview.width
        height: 50
        color: "pink"
        z: 3//设置层级避免滚动时，代理覆盖表尾

        Text {
            anchors.centerIn: parent
            font.pixelSize: 30
            text: "表尾"
        }
    }

    //设置表尾位置，默认是最后一行，overlayFooter表示最后一行并固定，更多请查看文档
    footerPositioning: ListView.OverlayFooter

    //文本高亮，也属于代理的一种
    highlight: Item {
        width: listview.width
        height: 50
        z: 2 //delegate的层级为1，highlight的层级为0，必须比代理的层级高，否则，高亮会被代理覆盖

        //非delegate属性无法访问model，所以需要脚本传递
        function setText(name, age) {
            nameHighlightText.text = name
            ageHighlightText.text = age
        }

        Rectangle {
            anchors.left: parent.left
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "cyan"

            Text {
                id: nameHighlightText
                anchors.centerIn: parent
                font.pixelSize: 30
            }
        }

        Rectangle {
            anchors.right: parent.right
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width / 2 - 5
            color: "cyan"

            Text {
                id: ageHighlightText
                anchors.centerIn: parent
                font.pixelSize: 30
            }
        }
    }

    //设置高光的移动速度
    highlightMoveDuration: 200

    //每条数据的间隔
    spacing: 10

    //添加代理时的动画，使用头插法时，使用addDisplaced过渡才生效
    add: Transition {
        NumberAnimation {
            //y轴发生改变时
            properties: "y"
            duration: 300
        }
    }

    //旧元素移动的过渡动画
    addDisplaced: Transition {
        NumberAnimation {
            //y轴发生改变时
            properties: "y"
            duration: 300
        }
    }

    //删除的过渡动画
    remove: Transition {
        NumberAnimation {
            //元素被移除时，透明度缓慢过渡
            properties: "opacity"
            from: 1
            to: 0
            duration: 300
        }
    }

    //给数据分区
    section {
        //需要分区的属性
        property: "name"

        //分区的依据，FirstCharacter根据首个字符，FullString根据整个字符
        criteria: ViewSection.FirstCharacter

        //分区显示的样式
        delegate: Rectangle {
            width: 50
            height: width
            radius: width / 2

            Text {
                anchors.centerIn: parent
                //section为内置属性，根据criteria显示
                text: section
            }
        }

        //代理的显示位置，CurrentLabelAtStart为显示在开头，其余根据文档查看
        labelPositioning: ViewSection.CurrentLabelAtStart
    }
}

Column {
    spacing: 10
    anchors.right: parent.right

    Button {
        text: "添加一条数据 "
        onClicked: {
            //count表示listview的数据总数
            listModel.append({name: "王五" + listview.count, age :16})
            //将滚动条移动到末尾
            listview.positionViewAtEnd()
        }
    }
    Button {
        text: "删除一条数据 "
        onClicked: {
            //传入删除索引，索引从0开始
            listModel.remove(listview.count - 1)
        }
    }
}
```

