## 64、C++访问qml控件

### 64.1、访问window根节点控件

<span style="background: yellow;">注意导入：QQmlProperty</span>

```c++
#include <QGuiApplication>
#include <QQmlApplicationEngine>
//访问属性需要导入
#include <QQmlProperty>

int main(int argc, char *argv[])
{
#if QT_VERSION < QT_VERSION_CHECK(6, 0, 0)
    QCoreApplication::setAttribute(Qt::AA_EnableHighDpiScaling);
#endif
    QGuiApplication app(argc, argv);

    QQmlApplicationEngine engine;
    const QUrl url(QStringLiteral("qrc:/main.qml"));
    QObject::connect(
        &engine,
        &QQmlApplicationEngine::objectCreated,
        &app,
        [url](QObject *obj, const QUrl &objUrl) {
            if (!obj && url == objUrl)
                QCoreApplication::exit(-1);
        },
        Qt::QueuedConnection);
    engine.load(url);

    //rootObjects()考虑了有多个根节点的情况，所以返回值是objectlist，需要获取第一个元素
    QObject* obj = engine.rootObjects().first();

    //改变obj（window）中的title属性
    QQmlProperty(obj, "title").write("hello window");
    //改变obj（window）中的width属性
    QQmlProperty(obj, "width").write(1200);

    return app.exec();
}
```

