<span style="background: yellow;">方法实现</span>

```c++
int testQmlSignal::getPro2() const
{
    return pro2;
}

void testQmlSignal::setPro2(int newPro2)
{
    if (pro2 == newPro2)
        return;
    pro2 = newPro2;
    emit pro2Changed();
}

int testQmlSignal::getPro1() const
{
    return pro1;
}

void testQmlSignal::setPro1(int newPro1)
{
    if (pro1 == newPro1)
        return;
    pro1 = newPro1;
    emit pro1Changed();
}
