### 74.3、轮播图1

```js
Item {
    id: rightCarouselItem
    width: 500
    height: parent.height
    clip: true
    anchors {
        left: parent.left
    }
    property int curImgIndex: 0 //存储当前轮播图片下标
    property int actualCurImgIndex: 0 //存储当前轮播图片实际下标，因为存储了两次，实际下标是当前下标的两倍

    //存储轮播图片
    ListModel {
        id: carouselImg
        Component.onCompleted: {
            let s = "qrc:/resources/carouselImg/"
            //顺序存储两次，依次轮转
            for (let i = 1; i <= 8; i++) {
                carouselImg.append({ img: s + `${i}.jpg` })
            }
            for (let i = 1; i <= 8; i++) {
                carouselImg.append({ img: s + `${i}.jpg` })
            }
        }
    }

    Timer {
        id: carouselChange
        repeat: true
        running: true
        interval: 4600
        // interval: 1200
        onTriggered: {
            // 滚动距离为图片宽度加间隔
            let skipXDistance = parent.width + carouselRow.spacing

            //如果第一轮图片结束，到了第二轮的首张图片就把前面的所有图片插入尾部，详细看示例图
            if (parent.actualCurImgIndex === carouselImg.count / 2) {
                for (let i = 0; i < carouselImg.count / 2; i++) {
                    let head = 0
                    carouselImg.append(carouselImg.get(head))
                    carouselImg.remove(head)
                }

                parent.actualCurImgIndex = 0//实际下标重新初始化
                //如果不return会导致listview没来得及缓冲尾部插入的图片导致滚动距离错误
                //需要等到下一次轮转
                return
            }

            parent.curImgIndex = (parent.curImgIndex + 1) % (carouselImg.count / 2)
            parent.actualCurImgIndex = (parent.actualCurImgIndex + 1) % carouselImg.count
            //console.log(carouselRow.contentX, " + ", skipXDistance)
            carouselRow.contentX += skipXDistance
        }
    }

    ListView {
        id: carouselRow
        orientation: ListView.Horizontal
        width: parent.width
        height: parent.height
        spacing: 20
        enabled: false //禁止滑动
        model: carouselImg

        // 轮转动画，当横轴移动时
        Behavior on contentX {
            id: behaviorX
            NumberAnimation {
                duration: 350
            }
        }

        delegate: Rectangle {
            id: imgEle
            height: carouselRow.height
            width: carouselRow.width
            radius: 15
            gradient: Gradient {
                orientation: Gradient.Horizontal
                GradientStop{ color: "#440096F2"; position: 0 }
                GradientStop{ color: "#66CA2F45"; position: 1 }
            }

            Image {
                width: height
                height: parent.height
                anchors.horizontalCenter: parent.horizontalCenter
                source: img
            }

            MouseArea {
                anchors.fill: parent
                cursorShape: Qt.PointingHandCursor
                hoverEnabled: true

                onEntered: {
                    parent.opacity = 0.7
                }

                onExited: {
                    parent.opacity = 1
                }
            }
        }
    }

    //轮播指示器
    Row {
        anchors {
            horizontalCenter: parent.horizontalCenter
            left: parent.left
            leftMargin: 10
            bottom: parent.bottom
            bottomMargin: 10
        }

        Repeater {
            model: carouselImg.count / 2

            delegate: Item {
                width: 17
                height: 10

                Rectangle {
                    anchors.centerIn: parent
                    width: 8
