# 一、需要实现的接口

```c
//初始化栈
void StackInit(stack* p);
//销毁栈
void StackDestroy(stack* p);
//入栈
void StackPush(stack* p, StackDataType x);
//出栈
void StackPop(stack* p);
//取出栈顶数据
StackDataType StackTop(stack* p);
//计算栈的大小
int StackSize(stack* p);
//栈的判空
bool StackEmpty(stack* p);
```

# 二、代码实现
## 1.创建栈
`栈可以使用数组或链表实现，这里使用的是数组`

```c
typedef int StackDataType;//栈中存储的数据为整型
//将其重命名的意义是方便以后更改数据类型

typedef struct Stack {
	StackDataType* vals;
	int top;//栈顶的下标
	int capacity;//记录数组的容量，到达上限时扩容
}stack;
```

## 2.各接口创建
### 1- 初始化栈

```c
void StackInit(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	p->vals = (StackDataType*)malloc(sizeof(StackDataType) * 4);
	p->capacity = 4;
	//设置数组的初始大小为4
	p->top = 0;//此时栈顶为0，无任何数据
}
```
### 2 - 销毁栈

```c
void StackDestroy(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	free(p->vals);//释放栈中的所有值
	p->vals = NULL;//置成空指针防止野指针的出现
	p->capacity = p->top = 0;
}
```
### 3 - 入栈

```c
void StackPush(stack* p, StackDataType x) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	if (p->top == p->capacity) {//栈顶如果等于容量就代表栈已经满了，需要扩容
		StackDataType* tmp = (StackDataType*)realloc(p->vals, sizeof(StackDataType) * (p->capacity * 2));
		//这里扩容为原容量的二倍
		if (tmp) {
			p->capacity *= 2;
			p->vals = tmp;
		}
		else {//若有扩容失败的情况就强制终止程序
			printf("realloc fail!\n");
			exit(-1);
		}
	}
	p->vals[p->top] = x;//将x插入栈顶
	p->top++;//栈顶为p->top - 1
}
```
### 4 - 出栈

```c
void StackPop(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	if (p->top > 0) {//要保证栈中至少存在一个数据才能出栈
		p->top--;
	}
	else {//无数据就强制终止程序
		printf("stack no data\n");
		exit(-1);
	}
}
```

### 5 -  取出栈顶数据

```c
StackDataType StackTop(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	if (p->top == 0) {//栈中无数据，强制终止程序
		printf("stack no data\n");
		exit(-1);
	}
	else {
		return p->vals[p->top - 1];//返回栈顶数据
		//这里因为初始化栈时p->top赋的初始值为0，入栈时将p->top++，所以栈顶数据是当前p->top所指向的后一位
	}
}
```
### 6 - 计算栈的大小

```c
int StackSize(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	return p->top;//初始从0开始，栈顶是p->top的后一位，所以当前p->top的值就是栈的数据个数
}
```
### 7 - 栈的判空

```c
bool StackEmpty(stack* p) {
	assert(p);//使用断言防止p为空指针，可以更好的找到错误

	return p->top == 0;//若栈顶为0则代表栈中无数据，返回true
	//栈顶不为0代表栈不为空，返回false
}
```
