void stacktest1() {
	stack p;//不需要赋值，使用StackInit
	StackInit(&p);//传参需要传地址

    //依次入数据 
	StackPush(&p, 1);
	StackPush(&p, 2);
	StackPush(&p, 3);
	StackPush(&p, 4);

    //一共入了四个数据
    printf("StackSize = %d\n", StackSize(&p));

	while (!StackEmpty(&p)) {
	//使用逻辑非运算符（非0为假，0为真），栈不为空时继续，为空时停止
	//因为栈为空返回true，不为空返回false
		printf("%d\n", StackTop(&p));//取出栈顶数据并输出
		StackPop(&p);//输出完之后将栈顶移除
	}

	StackDestroy(&p);//栈使用完毕需要销毁，防止内存泄漏
}

int main() {
	stacktest1();
	return 0;
}
