# 四、完整代码

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <assert.h>

typedef struct path {
    int row;
    int col;
} path;

typedef path StackDataType;

typedef struct Stack {
	StackDataType* vals;
	int top;
	int capacity;
}stack;

void StackInit(stack* p) {
	assert(p);

	p->vals = (StackDataType*)malloc(sizeof(StackDataType) * 4);
	p->capacity = 4;
	p->top = 0;
}

void StackDestroy(stack* p) {
	assert(p);
	free(p->vals);
	p->vals = NULL;
	p->capacity = p->top = 0;
}

void StackPush(stack* p, StackDataType x) {
	assert(p);

	if (p->top == p->capacity) {
		StackDataType* tmp = (StackDataType*)realloc(p->vals, sizeof(StackDataType) * (p->capacity * 2));
		if (tmp) {
			p->capacity *= 2;
			p->vals = tmp;
		}
		else {
			printf("realloc fail!\n");
			exit(-1);
		}
	}
	p->vals[p->top] = x;
	p->top++;
}

void StackPop(stack* p) {
	assert(p);

	if (p->top > 0) {
		p->top--;
	}
	else {
		printf("stack no data\n");
		exit(-1);
	}
}

StackDataType StackTop(stack* p) {
	assert(p);

	if (p->top == 0) {
		printf("stack no data\n");
		exit(-1);
	}
	else {
		return p->vals[p->top - 1];
	}
}

int StackSize(stack* p) {
	assert(p);

	return p->top;
}

bool StackEmpty(stack* p) {
	assert(p);

	return p->top == 0;
}

void PrintMaze(int** maze, int row, int col){
    int i = 0;
    for (i = 0; i < row; i++){
        int j = 0;
        for (j = 0; j < col; j++){
            printf("%d ", maze[i][j]);
        }
        printf("\n");
    }
}

bool isPass(int** maze, int row, int col, path cur){
    if (cur.row < row && cur.col < col
    && cur.row >= 0 && cur.col >= 0 && maze[cur.row][cur.col] == 0){
        return true;
    }
    return false;
}

bool FindMazeExit(int** maze, int N, int M, path cur, stack* exitPath){
    StackPush(exitPath, cur);
    maze[cur.row][cur.col] = 2;

    if (cur.row == N - 1 && cur.col == M - 1){
        return true;
    }
    path next = cur;

    next.row--;
    if (isPass(maze, N, M, next)){
        if (FindMazeExit(maze, N, M, next, exitPath)){
            return true;
        }
    }

    next = cur;
    next.row++;
    if (isPass(maze, N, M, next)){
        if (FindMazeExit(maze, N, M, next, exitPath)){
            return true;
        }
    }

    next = cur;
    next.col++;
    if (isPass(maze, N, M, next)){
        if (FindMazeExit(maze, N, M, next, exitPath)){
            return true;
        }
    }

    next = cur;
    next.col--;
    if (isPass(maze, N, M, next)){
        if (FindMazeExit(maze, N, M, next, exitPath)){
            return true;
        }
    }

    StackPop(exitPath);
    return false;
}

void PrintMazeExitPath(stack p){
    stack reversePath;
    StackInit(&reversePath);
    while (!StackEmpty(&p)){
        StackPush(&reversePath, StackTop(&p));
        StackPop(&p);
    }
    while (!StackEmpty(&reversePath)){
        path cur = StackTop(&reversePath);
        printf("(%d,%d)\n", cur.row, cur.col);
        StackPop(&reversePath);
    }
}

int main(){
    int i = 0;
    int N = 0, M = 0;

    while (scanf("%d%d", &N, &M) != EOF){
        int** maze = (int**)malloc(sizeof(int*)*N);
        for (i = 0; i < N; i++){
            maze[i] = (int*)malloc(sizeof(int)*M);
        }
        for (i = 0; i < N; i++){
            int j = 0;
            for (j = 0; j < M; j++){
                scanf("%d", &maze[i][j]);
            }
        }
        path cur = {0,0};
        stack exitPath;
        StackInit(&exitPath);
        FindMazeExit(maze, N, M, cur, &exitPath);
        PrintMazeExitPath(exitPath);
    }
}
